  else
  {
    /* Update the error code */
    hdma2d->ErrorCode |= HAL_DMA2D_ERROR_INVALID_CALLBACK;
    /* update return status */
    status =  HAL_ERROR;
  }

/* Release Lock */
  __HAL_UNLOCK(hdma2d);
  return status;
}

