{
  /* Process locked */
  __HAL_LOCK(hdsi);

/* Check function parameters */
  assert_param(IS_FUNCTIONAL_STATE(State));

/* Enable/Disable pull-down on lanes */
  hdsi->Instance->WPCR[0U] &= ~DSI_WPCR0_PDEN;
  hdsi->Instance->WPCR[0U] |= ((uint32_t)State << 18U);

/* Process unlocked */
  __HAL_UNLOCK(hdsi);

