if (hhrtim->State == HAL_HRTIM_STATE_BUSY)
  {
    return HAL_BUSY;
  }

/* Set the HRTIM state */
  hhrtim->State = HAL_HRTIM_STATE_BUSY;

if (TimerIdx == HRTIM_TIMERINDEX_MASTER)
