      break;
    }

default:
    {
      hhrtim->State = HAL_HRTIM_STATE_ERROR;

/* Process Unlocked */
      __HAL_UNLOCK(hhrtim);

break;
    }
  }

if (hhrtim->State == HAL_HRTIM_STATE_ERROR)
  {
    return HAL_ERROR;
  }

hhrtim->State = HAL_HRTIM_STATE_READY;

/* Process Unlocked */
  __HAL_UNLOCK(hhrtim);

return HAL_OK;
}

