        hirda->MspDeInitCallback = HAL_IRDA_MspDeInit;
        break;

default :
        /* Update the error code */
        hirda->ErrorCode |= HAL_IRDA_ERROR_INVALID_CALLBACK;

/* Return error status */
        status =  HAL_ERROR;
        break;
    }
  }
  else
  {
    /* Update the error code */
    hirda->ErrorCode |= HAL_IRDA_ERROR_INVALID_CALLBACK;

/* Return error status */
    status =  HAL_ERROR;
  }

return status;
}
#endif /* USE_HAL_IRDA_REGISTER_CALLBACKS */

