    hjpeg->Instance->CONFR1 |= JPEG_CONFR1_HDR;

/* Process unlocked */
    __HAL_UNLOCK(hjpeg);

/* Change the JPEG state */
    hjpeg->State = HAL_JPEG_STATE_READY;

return HAL_OK;
  }
  else
  {
    /* Process unlocked */
    __HAL_UNLOCK(hjpeg);

return HAL_BUSY;
  }
}

