      }
    }

return ((uint32_t)tail_pack[3] | ((uint32_t)tail_pack[2] << 8) | ((uint32_t)tail_pack[1] << 16) | \
            ((uint32_t)tail_pack[0] << 24));
  }
  else
  {
    hmmc->ErrorCode |= HAL_MMC_ERROR_BUSY;
    hmmc->RPMBErrorCode |= HAL_MMC_ERROR_RPMB_COUNTER_FAILURE;
    return 0;
  }
}

/**
