HAL_StatusTypeDef HAL_RTCEx_SetTamper(RTC_HandleTypeDef * hrtc, const RTC_TamperTypeDef * sTamper)
{
  uint32_t tmpreg;

/* Check the parameters */
  assert_param(IS_RTC_TAMPER(sTamper->Tamper));
