  assert_param(IS_TIM_CCXN_INSTANCE(htim->Instance, Channel));

switch (Channel)
  {
    case TIM_CHANNEL_1:
    {
      /* Disable the TIM Output Compare interrupt */
      __HAL_TIM_DISABLE_IT(htim, TIM_IT_CC1);
      break;
    }

case TIM_CHANNEL_2:
    {
